public class AuditedCartTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        AuditedCart quiet = new AuditedCart(null);
        String outcome;
        try {
            quiet.add("apple", 3);
            quiet.add("pear", 2);
            outcome = "no exception";
        } catch (RuntimeException e) {
            outcome = e.getClass().getSimpleName();
        }
        check("adding with a null log does not blow up", "no exception", outcome);
        check("total with a null log", 5, quiet.total());
        check("log() is never null", true, quiet.log() != null);

        String silentOutcome;
        try {
            quiet.log().record("direct call");
            silentOutcome = "no exception";
        } catch (RuntimeException e) {
            silentOutcome = e.getClass().getSimpleName();
        }
        check("the null object swallows messages", "no exception", silentOutcome);

        AuditedCart.ListLog log = new AuditedCart.ListLog();
        AuditedCart audited = new AuditedCart(log);
        audited.add("apple", 3);
        check("total with a real log", 3, audited.total());
        check("first recorded message", "[add apple x3]", log.messages().toString());
        audited.add("plum", 1);
        check("both messages recorded", "[add apple x3, add plum x1]", log.messages().toString());
        check("total after two adds", 4, audited.total());
        check("the real log was kept", true, audited.log() == log);

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

