import java.util.ArrayList;
import java.util.List;

interface AuditLog {

    void record(String message);
}

public class AuditedCart {

    private final AuditLog log;
    private int total;

    public AuditedCart(AuditLog log) {
        this.log = (log == null) ? new SilentLog() : log;
    }

    /** A do-nothing AuditLog: the null object. */
    static class SilentLog implements AuditLog {
        @Override
        public void record(String message) {
            // deliberately empty
        }
    }

    public void add(String item, int quantity) {
        total += quantity;
        log.record("add " + item + " x" + quantity);
    }

    public int total() {
        return total;
    }

    public AuditLog log() {
        return log;
    }

    /** A simple log that keeps every message, handy for testing. */
    static class ListLog implements AuditLog {
        private final List<String> messages = new ArrayList<>();

        @Override
        public void record(String message) {
            messages.add(message);
        }

        List<String> messages() {
            return messages;
        }
    }
}
